import {getStore,getContext,quoteTotal,balance,paidTotal,registerPayment,saveContact,confirmDelivery} from '../services/workshop-service.js';
import {e,money,date,stamp,field,select,checkbox,placeholder,selectOptions,link,button,submit,form,hint,pageHeader,bindForm,go,notify,showModal,table,badge} from '../components/ui.js';
import {icon} from '../components/icons.js';
import {permissionChecker} from '../services/permissions.js';
export function renderPayments({root,params,session}){
 const can=permissionChecker(session.role),canPay=can('pagos','registrar'),canDeliver=can('pagos','entregar');
 const s=getStore(),order=s.orders.find(o=>o.id===params.get('orden')),c=order?getContext(s,order):{},paid=order?paidTotal(s,order.id):0,pending=order?balance(s,order):0,delivery=order?.delivery;
 const contactOptions=()=>selectOptions(getStore().contacts.filter(x=>x.clientId===c.client?.id),x=>`${x.name} · ${x.documentType} ${x.documentNumber}`);
 root.innerHTML=pageHeader('Pago y entrega del vehículo','El pago y la identificación del receptor son acciones diferentes.')+
 form('1. PAGO DE LA ORDEN',select('Orden de trabajo','orderId',selectOptions(s.orders,o=>{const x=getContext(s,o);return `${o.id} / ${x.client?.name} / ${x.vehicle?.brand} ${x.vehicle?.model}`;}),order?.id||'','required')+
 `<div class="full-width payment-summary"><div><span>Total autorizado</span><strong>${money(order?quoteTotal(c.quote):0)}</strong></div><div><span>Pagado</span><strong>${money(paid)}</strong></div><div><span>Saldo pendiente</span><strong>${money(pending)}</strong></div>${order?badge(order.state):''}</div>`+
 field('Monto pagado','amount',order&&!delivery&&pending>0?(pending/100).toFixed(2):'','text','required inputmode="decimal" placeholder="450.00"')+select('Medio de pago','method',['Transferencia','Efectivo','Tarjeta']),submit('Registrar pago'),'payment-form')+
 form('2. ¿QUIÉN RETIRA EL VEHÍCULO?',`<p class="full-width form-description">Identifica a quien recoge el vehículo y comprueba su autorización para este retiro.</p><fieldset class="recipient-switch full-width"><legend class="sr-only">Persona que retira</legend>${['Titular / representante','Tercero'].map(kind=>`<label><input type="radio" name="kind" value="${e(kind)}" ${(delivery?.kind||'Titular / representante')===kind?'checked':''} ${delivery?'disabled':''}><span>${e(kind)}</span></label>`).join('')}</fieldset><div class="third-recipient full-width" ${delivery?.kind==='Tercero'?'':'hidden'}><div class="form-grid">${select('Contacto registrado vinculado al cliente','contactId',contactOptions(),delivery?.contactId||'',delivery?'disabled':'')}<div class="field-inline-link"><button type="button" class="secondary-button" id="new-contact" ${!order||delivery?'disabled':''}>+ Nuevo contacto</button></div></div></div>`+select('¿Cómo se verificó la autorización para este retiro?','method',[placeholder(),'Confirmación del titular','Documento','Representante facultado'],delivery?.method||'',delivery?'disabled':'required')+checkbox('Verifiqué identidad y autorización específica antes de entregar','verified',Boolean(delivery),delivery?'disabled':'')+hint('La persona que trajo el vehículo no queda autorizada automáticamente para retirarlo.'),submit('Confirmar entrega'),'delivery-form');
 root.querySelector('[name="orderId"]').onchange=ev=>go('pagos?orden='+ev.target.value);
 if(!order||pending<=0||delivery||!canPay)document.querySelector('#payment-form [type="submit"]').disabled=true;
 if(!order||delivery||!canDeliver)document.querySelector('#delivery-form [type="submit"]').disabled=true;
 if(!canPay||!canDeliver)root.insertAdjacentHTML('afterbegin',hint(`Tu rol no puede ${[!canPay&&'registrar pagos',!canDeliver&&'confirmar entregas'].filter(Boolean).join(' ni ')}.`));
 if(!canDeliver)document.getElementById('new-contact').disabled=true;
 root.querySelectorAll('[name="kind"]').forEach(radio=>radio.onchange=()=>root.querySelector('.third-recipient').hidden=radio.value!=='Tercero'||!radio.checked);
 bindForm('payment-form',data=>{const p=registerPayment(data,session.id);notify(`Pago ${p.id} registrado por ${money(p.amountCents)}.`);go('pagos?orden='+p.orderId);});
 bindForm('delivery-form',data=>{confirmDelivery({...data,orderId:order?.id},session.id);notify('Entrega confirmada y registrada.');go('pagos?orden='+order.id);});
 root.querySelector('#new-contact').onclick=()=>{
  const dialog=showModal('Nuevo contacto para retiro',hint('Esta persona se vincula al cliente seleccionado. Registrar el contacto no autoriza automáticamente la entrega.')+form('DATOS DEL CONTACTO',field('Nombre completo','name','','text','required maxlength="180"')+select('Tipo de documento','documentType',['DNI',{value:'CE',label:'Carné de extranjería'},'Pasaporte'])+field('N.º documento','documentNumber','','text','required maxlength="20"')+field('Teléfono internacional','phone','','tel','required maxlength="25" placeholder="+51987654321"')+select('Relación con el cliente','relation',['Conductor','Representante','Familiar','Otro']),submit('Guardar contacto')+button('Cancelar','cancel'),'contact-form'));
  dialog.querySelector('[data-action="cancel"]').onclick=()=>dialog.close();
  bindForm('contact-form',data=>{const contact=saveContact({...data,clientId:c.client.id});const sel=root.querySelector('[name="contactId"]');sel.innerHTML=contactOptions().map(o=>`<option value="${e(o.value)}" ${o.value===contact.id?'selected':''}>${e(o.label)}</option>`).join('');dialog.close();notify('Contacto registrado. Verifica la autorización para este retiro.');});
 };
 if(order){root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">PAGOS REGISTRADOS · ${e(order.id)}</h2>${table(['Pago','Fecha y hora','Monto','Medio','Registrado por'],s.payments.filter(p=>p.orderId===order.id).map(p=>[e(p.id),stamp(p.createdAt),money(p.amountCents),e(p.method),e(s.users.find(u=>u.id===p.createdBy)?.name)]),'Todavía no hay pagos registrados.')}${delivery?`<div class="success-strip">${icon('check')}Vehículo entregado el ${stamp(delivery.at)}. Retiro: ${e(delivery.kind==='Tercero'?s.contacts.find(x=>x.id===delivery.contactId)?.name:c.client?.name)}. Verificado por ${e(s.users.find(u=>u.id===delivery.by)?.name)} mediante ${e(delivery.method)}.</div>`:''}</section>`);}
}
